const assert=require('node:assert/strict'),fs=require('node:fs'),vm=require('node:vm');
const file='android-bundled-source-prep/build/web/big-brother-stock-managemenet/stock-allocation-prefill-v1.js';
const source=fs.readFileSync(file,'utf8');
const elements={activityDate:{value:'2026-11-19',dispatchEvent(){events.push('canonical')}},bbBatchTransactionDate:{value:'2026-11-19'},bbBatchSellingFrom:{value:'2026-11-19'},bbBatchSellingTo:{value:'2026-11-21',dispatchEvent(){events.push('range')}}};
const events=[];
const sandbox={document:{readyState:'loading',addEventListener(){},getElementById(id){return elements[id]}},Intl,Date,Event:class{},window:{}};
const instrumented=source.replace(/\}\)\(\);\s*$/, 'globalThis.test={allocationDate,applyAllocationDate};})();');
assert.notEqual(instrumented,source);
vm.runInNewContext(instrumented,sandbox);
const {allocationDate,applyAllocationDate}=sandbox.test;
assert.equal(allocationDate({fields:{date:'2026-12-01'}}),'2026-12-01');
const today=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Phnom_Penh',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
assert.equal(allocationDate({created:'2026-11-19T10:00:00Z'}),'2026-11-19');
assert.equal(allocationDate({created:'2026-11-19T18:00:00Z'}),'2026-11-20');
assert.equal(allocationDate({fields:{date:'2026-12-05'},created:'2026-11-19T10:00:00Z'}),'2026-12-05');
assert.equal(allocationDate({},'2026-11-20T00:00:00Z'),'2026-11-20');
const writer=fs.readFileSync('android-bundled-source-prep/build/web/big-brother-stock-allocation/mobile.html','utf8');
assert.ok(writer.includes('id="date" type="date" required'));
assert.ok(writer.includes("'controller','location','salesman','driver1','driver2','date'"));
assert.ok(source.includes('legacy creation date; verify before saving stock'));
assert.equal(allocationDate({fields:{date:'2026-02-30'}}),today);
applyAllocationDate('2026-12-01');
for(const el of Object.values(elements))assert.equal(el.value,'2026-12-01');
assert.deepEqual(events,['canonical','range']);
assert.ok(source.includes("if(flow!=='OUTFLOW')setFlow('OUTFLOW')"));
assert.ok(source.includes("if(movementType!=='BATCH_STOCK')setMovementType('BATCH_STOCK')"));
assert.ok(source.includes("await request('consume'"));
assert.ok(source.includes("event.stopImmediatePropagation()"));
console.log('PASS allocation date, selling window reset, redundant mode guard and one-use consume save guard');
